"use client";

import { useEffect, useRef } from "react";
import type { AnimationItem } from "lottie-web";
import { cn } from "@/lib/utils";

/**
 * Plays a Lottie animation from /public/lottie. The player (lottie-web's
 * light SVG build) loads only when the animation nears the screen, plays
 * only while visible, and with prefers-reduced-motion it stops on a still
 * frame (`still`, 0..1 of the animation) instead of playing.
 *
 * Decorative: the surrounding copy carries the meaning, so it's hidden from
 * assistive tech unless a `label` is given. Files are generated by
 * scripts/lottie-gen.py for now; designed files can replace them under the
 * same names.
 */
export function Lottie({
  src,
  className,
  label,
  loop = true,
  still = 0.75,
  speed = 1,
}: {
  src: string;
  className?: string;
  label?: string;
  loop?: boolean;
  still?: number;
  speed?: number;
}) {
  const box = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = box.current;
    if (!el || typeof IntersectionObserver === "undefined") return;
    let anim: AnimationItem | null = null;
    let cancelled = false;
    let visible = false;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const load = async () => {
      const { default: lottie } = await import("lottie-web/build/player/lottie_light");
      if (cancelled || anim) return;
      anim = lottie.loadAnimation({ container: el, renderer: "svg", loop, autoplay: false, path: src, rendererSettings: { preserveAspectRatio: "xMidYMid meet" } });
      anim.setSpeed(speed);
      anim.addEventListener("DOMLoaded", () => {
        if (!anim) return;
        if (reduce) anim.goToAndStop(Math.round(anim.totalFrames * still), true);
        else if (visible) anim.play();
      });
    };

    const io = new IntersectionObserver(
      ([e]) => {
        visible = e.isIntersecting;
        if (visible && !anim) void load();
        if (!anim || reduce) return;
        if (visible) anim.play();
        else anim.pause();
      },
      { rootMargin: "200px 0px" },
    );
    io.observe(el);
    return () => {
      cancelled = true;
      io.disconnect();
      anim?.destroy();
    };
  }, [src, loop, still, speed]);

  return <div ref={box} className={cn("relative", className)} role={label ? "img" : undefined} aria-label={label} aria-hidden={label ? undefined : true} />;
}
